ALTER TABLE public.hms_document_exports ADD COLUMN source_module text NOT NULL DEFAULT 'hms', ADD COLUMN access_level text NOT NULL DEFAULT 'edit';
ALTER TABLE public.hms_document_exports ADD CONSTRAINT export_module_allowed CHECK (source_module IN ('hms','organisation','employees','resource_plan','documents','planning','customers','finance')), ADD CONSTRAINT export_level_allowed CHECK (access_level IN ('view','edit'));
CREATE OR REPLACE FUNCTION public.can_access_document_export(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.hms_document_exports e WHERE e.id=_id AND e.created_by=auth.uid() AND public.has_company_access(auth.uid(),e.company_id,e.source_module,e.access_level)) $$;
REVOKE ALL ON FUNCTION public.can_access_document_export(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_document_export(uuid) TO authenticated;
ALTER POLICY hms_exports_read ON public.hms_document_exports USING ((source_module='hms' AND access_level='edit' AND public.has_company_access(auth.uid(),company_id,'hms','edit')) OR public.can_access_document_export(id));
ALTER POLICY hms_exports_create ON public.hms_document_exports WITH CHECK (created_by=auth.uid() AND public.has_company_access(auth.uid(),company_id,source_module,access_level) AND status='prepared' AND sent_at IS NULL AND sent_by IS NULL);
ALTER POLICY hms_exports_update ON public.hms_document_exports USING (status IN ('prepared','downloaded','failed') AND public.can_access_document_export(id)) WITH CHECK (created_by=auth.uid() AND status IN ('prepared','downloaded','failed') AND sent_at IS NULL AND sent_by IS NULL AND public.has_company_access(auth.uid(),company_id,source_module,access_level));
CREATE OR REPLACE FUNCTION public.freeze_export_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.source_module IS DISTINCT FROM OLD.source_module OR NEW.access_level IS DISTINCT FROM OLD.access_level THEN RAISE EXCEPTION 'Export scope is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER freeze_document_export_scope BEFORE UPDATE ON public.hms_document_exports FOR EACH ROW EXECUTE FUNCTION public.freeze_export_scope();
CREATE OR REPLACE FUNCTION public.can_access_dle_package_file(_package text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.compliance_response_packages p WHERE p.id::text=_package AND p.created_by=auth.uid() AND public.has_company_access(auth.uid(),p.company_id,'hms','edit')) OR EXISTS (SELECT 1 FROM public.hms_document_exports e WHERE e.id::text=_package AND e.created_by=auth.uid() AND public.has_company_access(auth.uid(),e.company_id,e.source_module,e.access_level)) $$;
CREATE OR REPLACE FUNCTION public.mark_documentation_downloaded(_export_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.hms_document_exports SET downloaded_at=now(), events=events || jsonb_build_array(jsonb_build_object('event_type','downloaded','actor_user_id',auth.uid(),'created_at',now(),'payload',delivery_metadata)) WHERE id=_export_id AND public.can_access_document_export(id); IF NOT FOUND THEN RAISE EXCEPTION 'Export access denied'; END IF; END $$;